<?php
session_start();if(empty($_SESSION['usuario_id'])||($_SESSION['usuario_rol']??'')!=='admin'){header('Location: ../index.php');exit;}require_once __DIR__.'/../backend/conexion.php';$rows=$pdo->query('SELECT p.id,p.nombre,p.stock,p.activo,COALESCE(SUM(CASE WHEN m.tipo="entrada" THEN m.cantidad WHEN m.tipo="salida" THEN -m.cantidad ELSE 0 END),0) movimientos FROM productos p LEFT JOIN movimientos_inventario m ON m.producto_id=p.id GROUP BY p.id ORDER BY p.stock ASC')->fetchAll();$hist=$pdo->query('SELECT m.*,p.nombre FROM movimientos_inventario m JOIN productos p ON p.id=m.producto_id ORDER BY m.id DESC LIMIT 100')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventario</title><style>body{font:15px Arial;background:#f4f6f8;margin:0}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white;margin-right:15px}.wrap{max-width:1100px;margin:28px auto;padding:0 18px}section{background:white;padding:18px;border-radius:12px;margin:16px 0;overflow:auto}table{width:100%;border-collapse:collapse;min-width:600px}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}.low{color:#c22;font-weight:bold}</style></head><body><header class="top"><b>Mi Store · Inventario</b>　<a href="index.php">Panel</a><a href="productos.php">Productos</a></header><main class="wrap"><h1>Control de inventario</h1><section><h2>Stock actual</h2><table><tr><th>Producto</th><th>Stock</th><th>Estado</th><th>Alerta</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nombre'])?></td><td><?=$r['stock']?></td><td><?=$r['activo']?'Activo':'Inactivo'?></td><td class="<?=$r['stock']<=5?'low':''?>"><?=$r['stock']<=5?'Stock bajo':'Normal'?></td></tr><?php endforeach?></table></section><section><h2>Historial de movimientos</h2><table><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Motivo</th></tr><?php foreach($hist as $r):?><tr><td><?=$r['creado_en']?></td><td><?=htmlspecialchars($r['nombre'])?></td><td><?=$r['tipo']?></td><td><?=$r['cantidad']?></td><td><?=htmlspecialchars($r['motivo']??'')?></td></tr><?php endforeach?></table><p>Para ajustar stock, usa Gestión de productos; cada ajuste queda registrado.</p></section></main></body></html>
